// HasSharedTrip applies the HasEdge predicate on the "shared_trip" edge.
func HasSharedTrip() predicate.TripMember {
	return predicate.TripMember(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SharedTripTable, SharedTripColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSharedTripWith applies the HasEdge predicate on the "shared_trip" edge with a given conditions (other predicates).
func HasSharedTripWith(preds ...predicate.SharedTrip) predicate.TripMember {
	return predicate.TripMember(func(s *sql.Selector) {
		step := newSharedTripStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

